// ==========================================
// ⚙️ LUNAS WIRKUNG: GETEILTES LEID (Rondra)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.1tBOnhW6okOKlMd4");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    // --- 2. WIRKENDEN PRÜFEN & QS HOLEN ---
    const casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Rondrakind!");
    }

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) {
        await casterActor.unsetFlag("world", "letzteGabenQS"); 
    }

    if (typeof testData !== "undefined" && testData) {
        qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);
    }

    const gabenName = "Geteiltes Leid";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const dauerMinuten = qsWert;

    // --- 3. ZIEL PRÜFEN (Muss leben!) ---
    let targetToken = game.user.targets.first();
    if (!targetToken) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte markiere (Target) zuerst das Token deines Ziels!");
    }
    let targetActor = targetToken.actor;
    if (!targetActor) {
        return ui.notifications.warn("Das gewählte Ziel hat keinen gültigen Charakterbogen!");
    }

    if (casterActor.id === targetActor.id) {
        return ui.notifications.warn("Luna sagt 🌙: Du kannst das Leid nicht mit dir selbst teilen!");
    }

    const actorType = (targetActor.type || "").toLowerCase();
    const species = (targetActor.system?.species?.value || targetActor.system?.details?.species || "").toLowerCase();

    const excludedWords = ["untot", "geist", "vampir", "leiche", "golem", "skelett", "zombie", "dämon", "homunkulus", "mumie"];

    if (excludedWords.some(w => species.includes(w)) || actorType === "spirit") {
        return ui.notifications.warn(`Luna sagt 🌙: Fehlschlag! ${targetActor.name} ist kein lebendiges Wesen (Erwachter, Tier oder Mensch).`);
    }

    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
    };

    let whisperOwnerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => whisperOwnerIds.add(id));
    getOwners(targetActor).forEach(id => whisperOwnerIds.add(id));
    let whisperTargets = Array.from(whisperOwnerIds).filter(id => game.users.get(id));

    // --- 4. EFFEKTE AUF BEIDE ANWENDEN ---
    const descCaster = `Du teilst das Leid von <b>${targetActor.name}</b>. Erleidet das Ziel Schaden, so erhaltet ihr beide jeweils die abgerundete Hälfte davon.`;
    const descTarget = `<b>${casterActor.name}</b> teilt dein Leid. Erleidest du Schaden, so erhaltet ihr beide jeweils die abgerundete Hälfte davon.`;

    for (let ef of casterActor.effects) { if ((ef.name || ef.label) === finalEffektName) await ef.delete(); }
    for (let ef of targetActor.effects) { if ((ef.name || ef.label) === finalEffektName) await ef.delete(); }

    // WICHTIG: Beide UUIDs werden fest im Effekt gespeichert!
    await DSK_FW.Effekt.Anwenden({
        name: finalEffektName, ahne: ahne, beschreibung: descCaster, gabeZiel: "erwachte", qs: qsWert, ziel: casterActor,
        flags: { dsk: { casterUuid: casterActor.uuid, targetUuid: targetActor.uuid } }
    });
    await DSK_FW.Effekt.Anwenden({
        name: finalEffektName, ahne: ahne, beschreibung: descTarget, gabeZiel: "erwachte", qs: qsWert, ziel: targetActor,
        flags: { dsk: { casterUuid: casterActor.uuid, targetUuid: targetActor.uuid } }
    });

    // --- 5. INITIALE CHATKARTE ---
    await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: casterActor }),
        content: `
            ${DSK_FW.UI.Header(finalEffektName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="text-align:center; font-weight:bold; font-size:1.15em; margin-bottom:8px;">Verbindung etabliert</p>
                <p style="font-size:0.95em; line-height:1.35;">
                    <b>${casterName}</b> formt ein Band zu <b>${targetActor.name}</b>.<br><br>
                    Jeder Schaden, der ab sofort gegen ${targetActor.name} gerichtet ist, wird abgerundet halbiert und auf beide verteilt!
                </p>
                <hr>
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerMinuten} Minuten (QS ${qsWert})</p>
            </div>
        `
    });

    // --- 6. DER KUGELSICHERE SCHADENS-WÄCHTER ---
    globalThis.geteiltesLeidHooks = globalThis.geteiltesLeidHooks || {};
    if (globalThis.geteiltesLeidHooks[targetActor.id]) {
        Hooks.off("createChatMessage", globalThis.geteiltesLeidHooks[targetActor.id]);
    }

    globalThis.geteiltesLeidHooks[targetActor.id] = Hooks.on("createChatMessage", async (msg) => {
        const activeEffekt = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (!activeEffekt) {
            Hooks.off("createChatMessage", globalThis.geteiltesLeidHooks[targetActor.id]);
            delete globalThis.geteiltesLeidHooks[targetActor.id];
            return;
        }

        const rawContent = msg.content || "";
        const cleanText = rawContent.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

        if (cleanText.includes("gewinnt gegen")) {
            const isTargetHit = rawContent.includes(targetActor.id) || cleanText.includes(targetActor.name);

            if (isTargetHit) {
                let damage = 0;
                const dmgMatch = rawContent.match(/Trefferpunkte.*?=\s*(\d+)/i) || rawContent.match(/Trefferpunkte\s*:\s*(\d+)/i);
                if (dmgMatch && dmgMatch[1]) {
                    damage = parseInt(dmgMatch[1], 10);
                }

                if (damage > 0) {
                    const splitDmg = Math.floor(damage / 2);

                    const whisperHtml = `
                        <div style="font-family: 'Signika', sans-serif;">
                            <div class="dskbox1">
                                <p style="display:flex; align-items:center; gap:8px;">
                                    <img src="${DSK_FW.Symbol(ahne)}" style="width:28px;">
                                    <b>Geteiltes Leid aktiv!</b>
                                </p>
                                <p style="text-align:center; font-weight:bold; margin-top:6px; color:#d9534f;">Angriff auf: ${targetActor.name}</p>
                            </div>
                            <div class="dskbox2" style="margin-top:10px;">
                                <p style="font-size:0.95em; line-height:1.35;">
                                    <b>${targetActor.name}</b> hätte gerade <b>${damage} TP</b> erlitten. <br>
                                    Durch die Ahnengabe wird der Schaden aufgeteilt. Beide erhalten jeweils <b>${splitDmg} TP</b>.
                                    <br><br>
                                    <span style="font-size:0.85em; color:#555;"><i>(Klicke einfach auf diesen Button, der Rest geschieht automatisch)</i></span>
                                </p>
                                <hr>
                                <button class="apply-geteilt-btn" 
                                        data-caster-uuid="${casterActor.uuid}" 
                                        data-target-uuid="${targetActor.uuid}" 
                                        data-dmg="${splitDmg}"
                                        style="width:100%; cursor:pointer; background:linear-gradient(#76301b,#582617); color:#f8f6f5; border:1px solid #000; padding:5px 8px; border-radius:3px; font-weight:bold; margin-top: 5px; text-align:center;">
                                    ${splitDmg} TP auf beide anwenden
                                </button>
                            </div>
                        </div>
                    `;

                    const whisperedMsg = await ChatMessage.create({
                        whisper: whisperTargets,
                        content: whisperHtml,
                        speaker: { alias: "Rondra" }
                    });

                    // NEUE BUTTON-LOGIK: Akteure werden direkt aus der UUID geladen!
                    Hooks.once("renderChatMessage", (message, html) => {
                        if (message.id !== whisperedMsg.id) return;
                        html.find(".apply-geteilt-btn").off("click").on("click", async (e) => {
                            e.preventDefault();
                            const btn = e.currentTarget;
                            const cUuid = btn.dataset.casterUuid;
                            const tUuid = btn.dataset.targetUuid;
                            const dmg = parseInt(btn.dataset.dmg, 10);

                            let cDoc = await fromUuid(cUuid);
                            let tDoc = await fromUuid(tUuid);

                            let cActor = cDoc?.documentName === "Token" ? cDoc.actor : cDoc;
                            let tActor = tDoc?.documentName === "Token" ? tDoc.actor : tDoc;

                            if (cActor && tActor) {
                                const curCasterHp = foundry.utils.getProperty(cActor, "system.stats.LeP.value") ?? 0;
                                const curTargetHp = foundry.utils.getProperty(tActor, "system.stats.LeP.value") ?? 0;

                                await cActor.update({ "system.stats.LeP.value": Math.max(0, curCasterHp - dmg) });
                                await tActor.update({ "system.stats.LeP.value": Math.max(0, curTargetHp - dmg) });

                                ui.notifications.info(`Geteiltes Leid: ${cActor.name} und ${tActor.name} erleiden je ${dmg} TP!`);

                                btn.disabled = true;
                                btn.innerText = "Schaden wurde angewendet";
                                btn.style.background = "#555";
                            } else {
                                ui.notifications.error("Akteure für Geteiltes Leid konnten nicht gefunden werden!");
                            }
                        });
                    });
                }
            }
        }
    });
})();
